css:
:root:not(.dark) [data-app-sidebar] { --foreground: #F3F5EF !important; --contrast-foreground: #F3F5EF !important; --card-foreground: #F3F5EF !important; --muted-foreground: #9B96A4 !important; --contrast-muted-foreground: #9B96A4 !important; --secondary-label: #9B96A4 !important; --contrast-secondary-label: #9B96A4 !important; --contrast-sidebar-foreground: #F3F5EF !important; --contrast-sidebar-muted-foreground: #9B96A4 !important; --info: #22DDF5 !important; --info-foreground: #22DDF5 !important; }
:root:not(.dark) [data-app-sidebar] [data-sidebar-row][aria-current="page"] { color: #170834 !important; --foreground: #170834 !important; --contrast-foreground: #170834 !important; --card-foreground: #170834 !important; --muted-foreground: #3D3352 !important; --contrast-muted-foreground: #3D3352 !important; --secondary-label: #3D3352 !important; --contrast-secondary-label: #3D3352 !important; --sidebar-foreground: #170834 !important; --contrast-sidebar-foreground: #170834 !important; --sidebar-muted-foreground: #3D3352 !important; --contrast-sidebar-muted-foreground: #3D3352 !important; --icon-muted: #3D3352 !important; --info: #170834 !important; --info-foreground: #170834 !important; }
:root:not(.dark) [data-workspace-titlebar-controls] [data-slot="toggle"][data-pressed], :root:not(.dark) [data-workspace-titlebar-controls] [data-slot="toggle"][aria-pressed="true"] { background-color: #8FE34F !important; color: #170834 !important; --control-icon-color: #170834 !important; }
:root:not(.dark) [data-workspace-area="conversation"] { background-color: #F3F5EF; background-image: url("data:image/svg+xml;base64,"); background-repeat: repeat; background-size: 15rem auto; }
:root:not(.dark) [data-slot="composer-host"] { border: 1px solid #170834 !important; border-radius: 15px !important; box-shadow: 0 4px 0 #170834 !important; background: #FFFFFF !important; }
:root:not(.dark) [data-slot="dialog-popup"], :root:not(.dark) [data-slot="popover-popup"], :root:not(.dark) [data-slot="menu-popup"] { border: 1px solid #170834 !important; border-radius: 15px !important; box-shadow: 0 6px 0 #000 !important; }
:root:not(.dark) [data-thread-details-card] { border: 1px solid #170834 !important; box-shadow: 0 3px 0 #170834 !important; }
:root:not(.dark) [data-user-message-bubble] { border-radius: 15px !important; }
:root:not(.dark) .chat-markdown a { color: #661AFF !important; }
:root:not(.dark) [data-user-message-bubble] { --info: #8FE34F !important; --info-foreground: #8FE34F !important; }
:root:not(.dark) [data-user-message-bubble] a, :root:not(.dark) [data-user-message-bubble] .chat-markdown a, :root:not(.dark) [data-slot="tooltip-popup"] a, :root:not(.dark) [data-slot="tooltip-popup"] .chat-markdown a { color: #8FE34F !important; }
:root:not(.dark) .chat-markdown-codeblock { border: 1px solid #170834 !important; border-radius: 12px !important; }
:root:not(.dark) [data-slot="tooltip-popup"] { background: #170834 !important; color: #F3F5EF !important; --foreground: #F3F5EF !important; --contrast-foreground: #F3F5EF !important; --popover-foreground: #F3F5EF !important; --muted-foreground: #9B96A4 !important; --contrast-muted-foreground: #9B96A4 !important; --secondary-label: #9B96A4 !important; }
:root:not(.dark) ::-webkit-scrollbar-thumb { background: rgba(23,8,52,0.15); border-radius: 4px; }
:root:not(.dark) ::-webkit-scrollbar-thumb:hover { background: rgba(23,8,52,0.25); }
